    if (r.review || r.practice) { var bh = el('button', 'btn ghost', '테스트 처음으로'); bh.type = 'button'; bh.addEventListener('click', function () { qz.run = null; drawQuiz(); }); row.appendChild(bh); box.appendChild(row); row = el('div', 'runrow'); row.hidden = true; }
    var b2 = el('button', 'btn' + (wrong.length ? ' ghost' : ''), '같은 조건으로 새 문제'); b2.type = 'button'; b2.addEventListener('click', function () { qz.lv = r.lv; qz.cat = r.cat; var have = pool(r.lv, r.cat); startQuiz(shuffle(have).slice(0, Math.min(qz.n, have.length))); }); row.appendChild(b2);
    var b3 = el('button', 'btn ghost', '단계 다시 고르기'); b3.type = 'button'; b3.addEventListener('click', function () { qz.run = null; drawQuiz(); }); row.appendChild(b3);
    box.appendChild(row);
    var weak = []; wrong.forEach(function (it) { if (it.id && weak.indexOf(it.id) < 0) weak.push(it.id); });
    if (weak.length) { box.appendChild(el('h3', null, '틀린 문제와 이어지는 실습')); var wr = el('div', 'runrow'); weak.forEach(function (id) { wr.appendChild(labLink(id, '실습')); }); box.appendChild(wr); }
