    if (f.member && f.owner !== T && f.active) sum.push('부모에 선언된 static 멤버를 자식 이름으로 쓰면 부모만 초기화됩니다. Child.' + mname + '라고 써도 Child의 static 블록은 실행되지 않습니다.');
