    var load = '        prices = repository.findAll();        // 가격표를 미리 읽어 둔다\n', clear = '        prices.clear();\n';
    var s = (k.bean ? '' : '@Component\n' + (proto ? '@Scope("prototype")\n' : '')) + 'class PriceCache' + (k.iface ? ' implements InitializingBean, DisposableBean' : '') + ' {\n';
