    var st = { boot: 'ing', call: '', called: false, steps: [], out: { t: '결과', s: '아직 없음', cls: 'ghost' }, sent: sent, tbl: coupon ? 'coupon' : 'member',
      rows: coupon ? [{ k: 'WELCOME', v: '가입 축하', cls: '' }] : this.members.map(function (m) { return { k: 'id ' + m[0], v: m[1] + ' · ' + m[2] + '세', cls: '' }; }) };
