  label: function (c) { return { fixed: 'where를 미리 붙임', nospace: '띄어쓰기 빠뜨림', join: '조건을 모아 이음', criteria: 'Criteria API', querydsl: 'Querydsl' }[c.how] + ' · 이름 ' + (c.name ? '입력' : '없음') + ' · 나이 ' + (c.age ? '입력' : '없음'); },
