    var st = { line: -1, name: c.name ? '김철수' : 'null', age: c.age ? '20' : 'null', pieces: [], full: { t: '', s: '', cls: 'ghost' }, run: { s: '아직 실행 전', cls: 'ghost' }, sql: 0 };
