    P.region('r2', 300, 122, 364, 94, str ? '힙 (풀 바깥)' : '힙 (캐시 밖)');
    var vars = [['a', s.a], ['b', s.b]]; if (s.objs.some(function (o) { return o.by.indexOf('part') >= 0; })) vars.push(['part', '객체']);
