    if (c.topic === 'fix') return '취약점 대응 · ' + (c.avail === 'yes' ? 'web-kit 2.0.1 있음' : 'web-kit 새 버전 없음') + ' · ' + { none: '대응 없음', bump: '버전 올림', override: 'json-lite 덮어씀' }[c.act];
    return '가짜 패키지 · 적은 이름 ' + this.NAME[c.name];
