        var v = res.ver[n], from = res.edges.filter(function (e) { return e[1] === n && e[0] !== 'constraints'; })[0][0], cls = '', note = '';
        if (flag && n === 'json-lite' && v === '1.2.0' && vulnKnown) { cls = 'bad'; note = '취약'; }
        if (flag && n === 'json-lite' && v === '1.2.1') { cls = 'good'; note = '고친 버전'; }
