    o.push('}', '');
    if (c.form === 'named') o.push('// Task를 구현한 클래스: run이 할 일을 작성한다', 'class Work implements Task {', '    public void run() {', '        System.out.println("일한다");', '    }', '}', '');
    o.push('public class Main {', '    public static void main(String[] args) {');
