    l.push('-- 행: 한 사람의 정보 한 줄을 넣는다', "INSERT INTO member VALUES (1, '김철수');", 'INSERT INTO member VALUES ' + this.row2[c.second] + ';', '', 'SELECT ' + c.col + ' FROM member;');
