      st.inc = { title: 'CREATE TABLE', sub: ['member', '(id, name)'] };
      st.chk = { cls: 'plain', title: 'DB가 기억', sub: ['열의 이름과', '타입'] }; st.flow = 'in';
      st.log.push(['CREATE TABLE member', '표가 만들어짐', 'good']);
