    var speed = { plain: 0, sha: 2e10, salt: 2e10, bcrypt: +c.cost === 10 ? 6000 : +c.cost === 12 ? 1500 : 375 }[H], verify = { plain: '거의 0', sha: '거의 0', salt: '거의 0', bcrypt: +c.cost === 10 ? '약 0.1초' : +c.cost === 12 ? '약 0.3초' : '약 1초' }[H];
