    var crack = H === 'plain' ? '필요 없음 (그대로 보임)' : dur(1e8 / speed), same = stored[0][1] === stored[1][1], table = H === 'plain' ? '필요 없음' : H === 'sha' ? '가능' : '불가능';
    function push(s, k, stage) { ev.push({ s: s, k: k, snap: { stage: stage } }); }
