    P.box('t1', 16, 118, 310, 54, { cls: s.t1 ? 'wait' : 'plain', title: next ? '스레드 1 (재사용됨: 다음 요청)' : '스레드 1 (철수의 요청)', sub: s.t1 || '대기' });
