  calc: function (c) { var copyIn = c.in === 'copy', a = copyIn ? 2 : 3, via = c.out === 'unmod' ? 'UnsupportedOperationException' : 'ok', fin = a + (c.out === 'none' ? 1 : 0); return { a: a, via: via, fin: fin }; },
