    var actNote = { prim: '칸에 든 값을 바꾼다', field: '가리키는 객체의 내용을 바꾼다', copy: '복사해 둔 객체의 내용을 바꾼다', renew: '칸에 다른 객체의 참조를 넣는다', str: '새 String 객체가 만들어진다' }[W];
