    P.size(680, 318);
    var cell = function (A, i, x, y, w, o) { var hit = s.hit && s.hit.arr === A.id && s.hit.idx === i; P.box('c' + A.id + '_' + i, x, y, w, 30, o || { cls: hit ? 'hot now' : 'plain', title: self.cellText(A.cells[i]), center: true }); };
