    var st = { cls: false, sv: '', a: false, av: '', b: false, bv: '', hot: '', by: '', ab: '', ex: '', err: '', errAt: '' };
    function push(s, k) { ev.push({ s: s, k: k || '', snap: JSON.parse(JSON.stringify(st)) }); }
