    P.box('sav', 388, 50, 262, 60, { cls: cls('sav'), title: 'SavingAccount', sub: ['Account의 자식 클래스'].concat(c.from === 'subThis' ? ['this.balance'] : c.from === 'subChild' ? ['SavingAccount other'] : c.from === 'subParent' ? ['Account other'] : []), right: reach('sav') });
