      if (d === 'sup' && o !== 'addInt') { st.comp = '오류'; push(opCode + ' 검사: 컴파일 오류입니다("' + j.msg + '").' + CAP + ' 실제 리스트가 List<Integer>일 수 있으므로 ' + j.box + '을 넣게 둘 수 없습니다. ? super Integer 리스트에 넣을 수 있는 것은 Integer입니다.', 'good'); }
